export const SS14_DPS_RULES = {"season":"SS14","releaseVerified":false,"generatedAt":"2026-10-16T14:41:40.267Z","pages":{"en/Armor":{"sourceUrl":"https://tlidb.com/en/Armor","sourcePageSha256":"55d5d29e8c575358d14a5ae19f11160a4b50467346d92eb2bcc8dce772bd2b4f","locale":"en","slug":"Armor","title":"Armor","body":"Helmet, Chest Armor, Gloves, and Boots\n\nArmor is a defensive mechanic against Hit Damage, Secondary Damage, and Damage Reflection.\nPlayers have 0 Armor by default. The lower limit of Armor is 0.\nOnly 60%% of the damage reduction provided by Armor will be applied to non-Physical Damage.\nThe max damage reduction provided by Armor is 80%%.\nYour Armor DMG Reduction for incoming damage is calculated using the following formula:\nYour DMG Reduction = Your Armor/(0.9 x Your Armor + 3000 + 300 x Min (Enemy Level, 90))\nMonsters' Armor DMG Reduction for incoming damage is calculated using the following formula:\nMonster DMG Reduction = Monster Armor/(0.9 x Monster Armor + 30000)\nMonster Armor in the formula increases with the enemy's level, ranging from 0 to 27273.\nDouble Armor\nWhen receiving damage, double the Armor value will be used to determine the damage reduction. This only takes effect in the damage calculation process and does not change the actual Armor value.","season":"SS14","authorityScope":"ss14-site-deployment","rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"ffb303522910edc98e9de4a9957686dbf8ed0ece995c5ce649aa44fb723df83b"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Ring_of_Ice","sourcePageSha256":"15a6cfdb18cdef5e0e10fc4b2a799947a637f823a6015b770461933bd494527f"}},"en/Resistance":{"sourceUrl":"https://tlidb.com/en/Resistance","sourcePageSha256":"16ddba5ccd70f4f5413fd5e58d2863354cd94597fe7d79e710bcd185268d3b13","locale":"en","slug":"Resistance","title":"Resistance","body":"+15% Elemental Resistance\n+20% chance to avoid Elemental Ailment\n\n+1% chance to avoid Elemental Ailments for every 1% effective Erosion Resistance\n\nResistance is an effective survival mechanic that directly reduces the corresponding type of damage taken by a certain percentage.\nThere are 4 types of Resistance: Fire Resistance, Lightning Resistance, Cold Resistance, and Erosion Resistance. Fire Resistance, Lightning Resistance, and Cold Resistance are collectively referred to as Elemental Resistance.\nWhen monsters deal a large amount of damage, it is mainly Elemental Damage, so increasing your Elemental Resistance will effectively reduce a large amount of Elemental Damage you'll take from them.\nEffective Resistance.\nYour initial Elemental Resistance and Erosion Resistance are 0.\nThe base Max Resistance is 60%% for all Resistances. This can be changed by increasing the Max Resistance %%. Max Resistance is capped at 90%%.\nThe final effective Resistance is the smaller value between the player's current Resistance and the Max Resistance","season":"SS14","authorityScope":"ss14-site-deployment","rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"ffb303522910edc98e9de4a9957686dbf8ed0ece995c5ce649aa44fb723df83b"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Ring_of_Ice","sourcePageSha256":"15a6cfdb18cdef5e0e10fc4b2a799947a637f823a6015b770461933bd494527f"}},"en/Resistance_Penetration":{"sourceUrl":"https://tlidb.com/en/Resistance_Penetration","sourcePageSha256":"4fc04d62dc098cf6a13147ff932414e39d8055c9e597b4bd5d04161717c77823","locale":"en","slug":"Resistance_Penetration","title":"Resistance Penetration","body":"When calculating the damage, the defender's Resistance is calculated at a lower value.\nAs a stat that counteracts Resistance, Resistance Penetration acts on the defender's effective Resistance in the damage calculation process.\nUpon inflicting damage, if the attacker has Resistance Penetration of a certain type, the defender's Resistance will be reduced accordingly by the value of the Resistance Penetration when calculating the damage.\nResistance Penetration does not change the actual value of the defender's Resistance.\nResistance Penetration takes effect on all forms of damage (Hit, DoT, Secondary, Reflect).","season":"SS14","authorityScope":"ss14-site-deployment","rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"ffb303522910edc98e9de4a9957686dbf8ed0ece995c5ce649aa44fb723df83b"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Ring_of_Ice","sourcePageSha256":"15a6cfdb18cdef5e0e10fc4b2a799947a637f823a6015b770461933bd494527f"}},"en/Armor_DMG_Mitigation_Penetration":{"sourceUrl":"https://tlidb.com/en/Armor_DMG_Mitigation_Penetration","sourcePageSha256":"878a939390cb838700a2b6a80bc00615ba3a98fcfa0a65cbea842e56ddfa268b","locale":"en","slug":"Armor_DMG_Mitigation_Penetration","title":"Armor DMG Mitigation Penetration","body":"When calculating the damage, the damage reduction provided by the defender's Armor is calculated at a lower value.\nWhen calculating Hit Damage, if the attacker has Armor DMG Mitigation Penetration, the corresponding value will be deducted from the damage reduction provided by the defender's Armor.\nArmor DMG Mitigation Penetration doesn't change the actual Armor.\nArmor DMG Mitigation Penetration can reduce the damage reduction provided by Armor to a negative value and additionally increase the damage taken by the defender by the corresponding value.","season":"SS14","authorityScope":"ss14-site-deployment","rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"ffb303522910edc98e9de4a9957686dbf8ed0ece995c5ce649aa44fb723df83b"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Ring_of_Ice","sourcePageSha256":"15a6cfdb18cdef5e0e10fc4b2a799947a637f823a6015b770461933bd494527f"}},"en/Lucky":{"sourceUrl":"https://tlidb.com/en/Lucky","sourcePageSha256":"fb2fb234134f6509d601f08a4aa6390a2a03097bfb4657abc718e1783b13956f","locale":"en","slug":"Lucky","title":"Lucky","body":"Performs a random check or random roll twice and picks the result that benefits you the most\n\nCertain random results in combat are affected by Luck: When Lucky, the result is rolled multiple times and the more favorable one is kept. When Unlucky, the less favorable one is kept. The two effects can cancel each other out.\nLucky & Unlucky\nCertain random results in combat (such as damage rolls, Critical Strikes, Blocking, Evading and more) are affected by Lucky and Unlucky. They take effect by changing the number of rolls for the result:\nLucky: The result is rolled twice, and the more favorable one is kept.\nVery Lucky: The result is rolled three times, and the most favorable one is kept.\nUnlucky: The result is rolled twice, and the less favorable one is kept.\nWhen Lucky and Unlucky are both present, they cancel each other out. When Very Lucky and Unlucky are both present, they cancel into Lucky.","season":"SS14","authorityScope":"ss14-site-deployment","rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"ffb303522910edc98e9de4a9957686dbf8ed0ece995c5ce649aa44fb723df83b"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Ring_of_Ice","sourcePageSha256":"15a6cfdb18cdef5e0e10fc4b2a799947a637f823a6015b770461933bd494527f"}},"en/Spell_Burst":{"sourceUrl":"https://tlidb.com/en/Spell_Burst","sourcePageSha256":"d8e24ab448bebf84dfedfd9d2d138bb1a3ccc536243aae915555040ef16ff4a7","locale":"en","slug":"Spell_Burst","title":"Spell Burst","body":"Automatically uses a Spell Skill a certain number of times.\nWhen Spell Burst is fully charged, the next Spell Skill used will activate Spell Burst, which will consume all stacks charged and automatically use the Spell Skill the same number of times.\nSkills that have a cooldown, Triggered Skills, Sentry Skills, Channeled Skills, and Combo Skills cannot activate Spell Burst.\n\nHero's Resourcefulness\n\nBurst becomes Burst Blast and can activate Spell Burst\nAll conditions of this trait that trigger on attack are changed to trigger on hit\nThe Base Trait effect that generates Rage from using Melee Skills is changed to generating Rage upon skill use. The effect that triggers Burst on attack hit is changed to triggering Burst Blaston hit\n\nHero Trait Exclusive: Berserker Rehan|Anger\n\nTelepathy Expert\n\nWhen Spacetime Illusion consumes Spell Burst, it also attempts to consume Spell Burst for Youga\n-20% additional Spell Burst Hit Damage\n\nHero Trait Exclusive: Spacetime Witness Youga | Spacetime Illusion\n\nFifth Cosmic Velocity\n\n-99% additional Spell Burst Charge Speed\n100% chance to immediately gain 2 stack(s) of Spell Burst Charge. Interval: 0.03s\n-20% additional Spell Burst Hit Damage\n\nHero Trait Exclusive: Spacetime Witness Youga | Spacetime Illusion\n\nPlay Safe\n\n100% of Cast Speed bonuses and additional bonuses is also applied to Spell Burst Charge Speed\n-33% additional Spell Burst Charge Speed\n+40% additional Hit Damage for skills cast by Spell Burst\n\nSquidnova\n\n+16% additional Hit Damage for skills cast by Spell Burst for 10s.\n\nSpell Program\n\n+1 Max Spell Burst and +5% additional Spell Damage for Minions summoned by this skill\n\nEffect: Spell Burst\n\n+5% additional Hit Damage for skills cast by Spell Burst\nWhen Spell Burst is fully charged, triggers the Main Spell Skill on the nearest enemy within 25m and attempts to activate the Main Spell Skill's Spell Burst\n-30% Movement Speed\n\nBurst Pressurization\n\n+1 Max Spell Burst\n\nBurst Overload\n\n+2 Max Spell Burst\n+1s Cooldown for this skill, and it cannot trigger Spell Burst\n\nAutomatically casts a Spell Skill a certain number of times.\nSpell Burst\nWhen Spell Burst is fully charged, casting a Spell Skill will activate Spell Burst, which will consume all stacks of Spell Burst charged and automatically cast the Spell Skill the same number of times as the number of stacks consumed.\nSkills that are cast by Spell Burst, skills with a cooldown, Summon Skills, Sentry Skills, Channel Skills, and Triggered Skills cannot activate Spell Burst.\nThe Spell Skill that activates the Spell Burst is considered a skill cast by Spell Burst.\nSpell Burst Charge cannot go beyond Spell Burst's upper limit. Spell Burst can only be cast when Max Spell Burst is no lower than 1.\nSpell Burst Charge Speed\nSpell Burst will be fully charged within 2s. Spell Burst Charge Speed will increase the restoration speed of Spell Burst Charge.\nFull Spell Burst Charge Restoration Time = 2 / (100 + Spell Burst Charge Speed)% x (100 + additional Spell Burst Charge Speed 1)% x (100 + additional Spell Burst Charge Speed 2)%...\n\nSpell Burst\n\nTorchlight Infinite season 3 new spell mechanic: Spell Burst.\n\nAdded an upgrade system for spell skills. Consume spell burst when using or triggering channeled spell skills. According to the number of spell burst stacks consumed, automatically cast multiple spell skills in a burst in a short period of time.\n\n- When Spell Burst is fully charged, casting a Spell Skill will activate Spell Burst. When Spell Burst is cast, it will consume all stacks charged and cast the Spell Skill a number of times equal to the number of stacks consumed.\n\n- Skills that have a cooldown, Summon, Sentry, and Channeled Skills cannot activate Spell Burst.\n\n- The Spell Skill that activates the Spell Burst is considered a skill cast by Spell Burst.\n\n- Spell Burst Charge cannot go beyond Spell Burst's upper limit.\n\n- At least 1 Max Spell Burst is required before Spell Burst can be cast.\n\n- Spell Burst Charge will be fully charged in 2s.\n\n- Spell Burst Charge Speed will increase the restoration speed of Spell Burst Charge.\n\nSpell Burst Guides\n\nWe have designed spell burst, a new developed system for spells with spell burst. Hunters can consume spellburst Stacks when using or triggering Channel spell skills based on the number of spellburst stacks consumed. They can automatically cast multiple spell skills in a burst within a short period of time allowing for easy semi-automatic spell casting.\n\nSpell Burst is a powerful development system for spells. It enables Hunters to have a relaxed and smooth map clearing experience. It also allows them to move around neatly avoid enemy damage. However spellpers can only be consumed when it's at maximum Stacks. So, don't forget to upgrade the charge speed of Spell Burst when upgrading cast speed. We believe the additional of spell burst will bring spells to prominence.","season":"SS14","authorityScope":"ss14-site-deployment","rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"ffb303522910edc98e9de4a9957686dbf8ed0ece995c5ce649aa44fb723df83b"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Ring_of_Ice","sourcePageSha256":"15a6cfdb18cdef5e0e10fc4b2a799947a637f823a6015b770461933bd494527f"}},"en/Double_Damage":{"sourceUrl":"https://tlidb.com/en/Double_Damage","sourcePageSha256":"0c10dd75de4d69b66f69022a6f31b893934b1b53cf5fcd23ee4f498bb6b30068","locale":"en","slug":"Double_Damage","title":"Double Damage","body":"There's a chance to deal Double Damage on hit\n\nThere's a chance to deal Double Damage on hit.\nThere is a chance to deal Double Damage on hit according to the Double Damage chance.\nAll Double Damage chances that apply to the damage are stacked before the final determination.\nDouble Damage chance only applies to Hit Damage.","season":"SS14","authorityScope":"ss14-site-deployment","rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"ffb303522910edc98e9de4a9957686dbf8ed0ece995c5ce649aa44fb723df83b"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Ring_of_Ice","sourcePageSha256":"15a6cfdb18cdef5e0e10fc4b2a799947a637f823a6015b770461933bd494527f"}},"en/Critical_Strike":{"sourceUrl":"https://tlidb.com/en/Critical_Strike","sourcePageSha256":"fb58c242f4720c7fda18e83b7a458bd2373257df0c38858b86083c67cf85496e","locale":"en","slug":"Critical_Strike","title":"Critical Strike","body":"There is a chance to deal a Critical Strike when dealing Hit Damage.\nThere is a chance to deal a Critical Strike when dealing damage. If a skill can deal damage more than once (such as Spiral Strike), the Critical Strike determination is usually only carried out once.\nCritical Strike Rating\nWhen attacking, the base Critical Strike Rating of the weapon will be factored in when calculating the Critical Strike Rating of the skill. When casting a spell, the base Critical Strike Rating of the spell will be factored in when calculating the Critical Strike Rating of the skill.\nFinal Critical Strike Rating = The sum of Base Critical Strike Rating x (1 + all non-additional bonus percentages) x (1 + additional bonus percentage 1) x (1 + additional bonus percentage 2)...\nCritical Hit Chance = Final Critical Strike Rating/100.\nCritical Strike Damage\nAll units have 150% Critical Strike Damage by default.\nWhen dealing a Critical Strike, the damage dealt by the hit becomes: The original damage x the Critical Strike Damage percentage.","season":"SS14","authorityScope":"ss14-site-deployment","rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"ffb303522910edc98e9de4a9957686dbf8ed0ece995c5ce649aa44fb723df83b"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Ring_of_Ice","sourcePageSha256":"15a6cfdb18cdef5e0e10fc4b2a799947a637f823a6015b770461933bd494527f"}},"en/Character_Build":{"sourceUrl":"https://tlidb.com/en/Character_Build","sourcePageSha256":"d9dfe52714222aa2fe72a23b551c808768175ddd10337d7dd6d73b24354ceb01","locale":"en","slug":"Character_Build","title":"Character Build","body":"Units are defeated when their Life is 0\n\nMax Life\nHeroes initially start with 50 Max Life\nEach level gained increases Max Life by 13\nEach point of Strength increases Max Life by 0.2\n\nRelevant Stats\nStrength\nMax Life\nMax Life %\nAdditional Max Life %\n\nLife Restoration Over Time\nRelevant Stats\nLife Regeneration Per Second\nLife Regeneration % Per Second\nLife Regeneration Speed\n\nLife Regain\nInstantly returns a portion of the character's lost Life on hit, up to 30% Life\nRegain has a Regain Interval, and the base interval is 0.5 seconds\nRelevant Stats\nLife Regain %\nAdditional Regain Interval %\n\nInstant Restoration\nInstantly restores a certain amount of Life when the event corresponding to the affix takes place\nFor example:\nWhen suffering a Severe Injury, instantly restores 35% of Lost Life\nRestores 5% Life on defeat\n\nEnergy Shield is a defense stat. When taking damage, Energy Shield will be reduced before Life\n\nMax Energy Shield\nHeroes do not start with any Energy Shield, and Energy Shield is provided by Talents, gear, skills, and other systems\nEach Intelligence increases Max Energy Shield by 0.05%\nRelevant Stats\nMax Energy Shield\nMax Energy Shield %\nAdditional Max Energy Shield %\nGear Energy Shield\nGear Energy Shield %\n\nAfter not taking damage for a period of time (excludes Life Cost and Injury Buffer), if the current Energy Shield is less than the Max Energy Shield, the Energy Shield starts to charge. The base Charge Interval is 2 seconds. When the character's Max Energy Shield is 0, the character cannot gain Energy Shield Charge. Heroes have 20% Energy Shield Charge per second by default\nRelevant Stats\nEnergy Shield Charge Speed %\nAdditional Energy Shield Charge Speed %\nCharge Interval %\nAdditional Energy Shield Charge Interval %\n\nInstantly returns a portion of the character's lost Energy Shield on hit, up to 30% Energy Shield\nRegain has a Regain Interval, and the base interval is 0.5 seconds\nRelevant Stats\nEnergy Shield %\nAdditional Regain Interval %\n\nInstantly restores a certain amount of Energy Shield when the event corresponding to the affix takes place\nFor example:\nWhen evading, instantly restores 12% of missing Energy Shield\nRestores 5% Energy Shield when blocking\n\nMana is used to cast skills. Skills cannot be cast when they cost more than the character's current Mana\n\nMax Mana\nHeroes have 40 Max Mana by default\nEach level increases Max Mana by 5\nEach Intelligence increases Max Mana by 0.5\nMax Energy Shield Calculation Rules\nRelevant Stats\nIntelligence\nMax Mana\nMax Mana %\nAdditional Max Mana %\n\nHeroes regenerate 7 Mana per second by default\nHeroes regenerate 1.75% Mana per second by default\nRelevant Stats\nMana Regeneration Per Second\nMana Regeneration % Per Second\nMana Regeneration Speed %\n\nInstantly restores a certain amount of Mana when the event corresponding to the affix takes place\nFor example:\nRestores 5 Mana on hit\nRestores 1% Mana when using skills.\n\nMonsters deal five types of Damage: Physical, Fire, Cold, Lightning, and Erosion.\nFire, Cold, and Lightning Damage are collectively referred to as Elemental Damage.\nThe most dangerous skills of enemies are mainly Elemental. Thus, increasing your Elemental Resistance will effectively prevent you from taking lots of Elemental Damage.\n\nHeroes start with 0 Elemental Resistance and Erosion Resistance. At Lv.48, Lv.58, and Lv.80, heroes will be inflicted with -20% to all Resistances.\nThe base Max Resistance is 75% for all Resistances. This can be changed by increasing the Max Resistance %, which can increase the Max Resistance to 95%.\nThe final effective Resistance is the smaller value between the player's current Resistance and the Max Resistance\nRelevant Stats\nResistance %\nMax Resistance %\n\nAs a stat that counteracts Resistance, Resistance Penetration acts on the defender's effective Resistance in the damage calculation process.\nWhen dealing damage, if the attacker has Resistance Penetration of a certain type, the defender's Resistance will be reduced accordingly by the value of the Resistance Penetration when calculating the damage.\nResistance Penetration does not change the value of the defender's Resistance.\nResistance Penetration takes effect on all forms of damage (Hit, DoT, Secondary, Reflect).\n\nIf you have Ignore Resistance, ignore Resistance and Resistance Penetration in the damage calculation process\n\nArmor is a defensive mechanic against Hit, Secondary, and Reflected Damage\nCharacters start with 0 Armor by default\nRelevant Stats\nArmor\nArmor %\nAdditional Armor %\nGear Armor\nGear Armor %\n\nDamage reduction provided by Armor = Armor/(Armor x0.9+30,000). The max damage reduction provided by Armor is 80%.\nOnly 60% of the damage reduction provided by Armor will work for Non-Physical Damage.\n\nDouble Armor\nWhen receiving damage, double the Armor value will be used to determine the damage reduction. This only takes effect in the damage calculation process and does not change the actual Armor value\n\nEvasion is a defensive mechanic against Hit Damage. When the damage of a hit is evaded, the hit does not deal any damage or trigger its hit effects and subsequent effects. The chance of evading an attack is determined by the attacker's Accuracy and the target's Evasion Rate.\n\nHeroes' hits against monsters will not be evaded\nEvasion\nCharacters start with 0 Evasion by default, which is its lowest value\nEach level increases Evasion by 3\nEach Dexterity increases Evasion by 0.02%\nRelevant Stats\nEvasion\nEvasion %\nAdditional Evasion %\nGear Evasion\nGear Evasion %\n\nEvasion Rate\nEvasion Rate =1-1.15x attacker's Accuracy/(attacker's Accuracy +0.5x defender's Evasion^0.75), which means it is determined by the attacker's Accuracy and the defender's Evasion\nThe maximum Evasion rate is 75%, and the minimum Evasion rate is 0%\nFor Spell Damage, Evasion drops by additional 40% by default\nCurrently, the highest Accuracy monsters can have is 1,247\n\nBlocking is a defensive mechanic that counteracts Hit and Reflected damage. When taking Hit or Reflected damage, whether this damage is blocked will be determined based on the Attack or Spell tags of the source of this damage and the hero's corresponding Attack and Spell Block Chance. When blocking successfully, the damage will be reduced based on the Block Ratio and additional damage blocked.\n\nHeroes start with 0 Block Chance. The Block Chance includes the Attack Block Chance and Spell Block Chance. When taking damage, the corresponding tag is applied to determine whether the block is successful or not. The Block Chance from different sources can be stacked up to the maximum Block Chance of 100%\nRelevant Stats\nBlock Chance %\nAttack Block Chance %\nSpell Block Chance %\nHeroes start with a Block Ratio of 35% by default, which can be increased up to 75%. After a successful block is determined, a corresponding amount of damage will be offset according to the Block Ratio.\nHeroes do not have additional damage blocked by default. When both Block Ratio and a fixed Block Chance are available, the Block Ratio is factored into the calculation before the fixed Block Chance\nRelevant Stats\nBlock Ratio %\nAdditional Damage Blocked\n\nDamage Avoidance is a defensive mechanic that counteracts Hit Damage, Reflected Damage, and Secondary Damage. The Damage Avoidance Chance from different sources can stack.\nHeroes start with 0% Damage Avoidance by default\nWhen damage is successfully avoided, the hit is still deemed to be successful, and the attacker's hit-related effects will still be triggered. However, the defender will not take any damage or be inflicted with any ailments or control effects.\nRelevant Stats\nDamage Avoidance Chance %\n\nAdditional damage reduction is a defensive mechanic that counteracts all types of damage. Damage reduction from different sources multiplies independently\n\nThe maximum Damage Mitigation for each source of additional damage reduction is 90%\n\nInjury Buffer is a defensive mechanic that counteracts Hit Damage. When receiving Hit Damage, part of the damage is not settled directly. Instead, this damage will be settled once every 0.5s in a special form over the next 4s. Damage settled by Injury Buffer is not affected by other tags and does not trigger damage-related events. The Injury Buffer proportion from different sources can stack.\n\nWhen calculating the damage mitigation for the defender, the damage conversion will change the type of damage received and calculate the corresponding damage mitigation after the conversion. The proportion of damage conversion from different sources can be stacked. After exceeding 100%, it will be redistributed according to the proportion of each source.\n\nThe base duration is 10s. Each stack of Tenacity Blessing provides an additional 4% reduction in damage received. The base upper limit of Tenacity Blessing is 4 stacks.\nThe base duration of Tenacity Blessing is 10s.\nThe duration of all stacks of Tenacity Blessing is refreshed when obtaining Tenacity Blessing. All stacks of Tenacity Blessing will be lost if the duration ends.\n\nEach stack of Agility Blessing provides 6% Movement Speed, Attack Speed, and Cast Speed. The base upper limit of Agility Blessing is 4 stacks.\nThe base duration of Agility Blessing is 10s.\nThe duration of all stacks of Agility Blessing is refreshed when obtaining Agility Blessing. All stacks of Agility Blessing will be lost if the duration ends.\n\nEach stack of Focus Blessing provides a 4% chance to deal Double Damage. The base upper limit of Focus Blessing is 4 stacks.\nThe base duration of Focus Blessing is 10s.\nThe duration of all stacks of Focus Blessing is refreshed when obtaining Focus Blessing. All stacks of Focus Blessing will be lost if the duration ends.\n\nWhile Fervor is active, you'll gain 1 point of Fervor Rating when hitting an Elite.\nFervor Rating Base Effect: Each Fervor Rating provides +2% Attack and Spell Critical Strike Rating. The maximum amount of Fervor Rating is 100 points.\nThe base duration is 10s.\n\nGain a Barrier that absorbs damage equal to 20% of your Max Life and Energy Shield.\nThe Barrier's base absorption is 50%.\nNew Barriers can't be obtained while a Barrier lasts.\nA Barrier is lost when its duration ends or when the Barrier value drops to 0.\nThe base duration is 10s.\n\nGain 100 points of Blur Rating when obtaining Blur.\nOnce 100 points of Blur Rating is gained, 10% of Max Blur Rating is lost per second. Blur is lost once Blur Rating drops to 0.\nBlur Base Effect: +0.3% Evasion and +0.3% chance to avoid damage for every point of Blur Rating you have.\nMax Blur Rating is 100 points.\n\nStacks up to 5 times.\nThe base duration is 5s.\nThe duration of Focus is refreshed when obtaining Focus.\nFocus provides different buffs according to your skills, gear, etc.\n\nReduces damage taken by 25%. Stacks up to 1 time.\nThe base duration is 4s.\nThe Hardened status can only be obtained through the support skill Hardened.\n\nAdditionally increases damage taken by 10%. Stacks up to 1 time.\nThe base duration is 4s.\nParalysis is a control status.\n\nEach stack reduces Attack Speed, Cast Speed, and Movement Speed by 6%. Stacks up to 5 times.\nThe base duration is 4s.\nThe duration of the Slow status is refreshed whenever Slow is inflicted.\nSlow is a control status.\n\nThere are 4 main ways to deal damage in the game:\nHit Damage\nDamage Over Time\nSecondary Damage\nReflect Damage\n\nHit Damage is usually dealt by Attacks or Spells and is settled each time. Unless specified, damage dealt by skills is Hit Damage.\n\nThe following mechanics are specific to hit damage:\nAccuracy/Evade\nCritical Strike\nDamage Conversion/Addition\nDouble Damage\nInjury Transfer\nInjury Buffer\nBlock\nAvoidance\nSevere Injury\n\nDamage Over Time deals damage to the target continuously for a period of time.\nDamage Over Time dealt by skills is skill effects that benefit from affixes such as \"+10% Skill Effect Duration\", etc.\n\nThe following mechanics are specific to Damage Over Time:\nAffliction\nReaping\n\nSecondary Damage is usually an additional effect of certain actions, such as \"Makes enemies explode on defeat\".\nSecondary Damage is neither Hit Damage nor Damage Over Time, so it will not be enhanced by special mechanics of Hit Damage and Damage Over Time.\n\nAll damage dealt must be one of the following 5 types of damage:\nPhysical\nFire\nCold\nLightning\nErosion\n\nPhysical Damage received from hits can be reduced by Armor, while the other forms and types of damage (Hit, DoT, Secondary, Reflect) are reduced by the corresponding type of resistance.\n\nLike most stats, the final value of the attacker's damage = base damage x (100 + all non-additional bonuses)% x (100 + additional bonus 1)% x (100 + additional bonus 2)%...\n\nThe base value of Attack Speed depends on the Weapon Attack Speed.\nThe Weapon Attack Speed is determined by the base speed of the weapon and the affixes of the weapon that affect its Attack Speed.\nWhen Dual Wielding, the Weapon Attack Speed is the average Attack Speed of the 2 weapons.\nIn most cases, the character's final Attack Speed = Weapon Attack Speed x (100 + all non-additional bonuses)% x (100 + additional bonus 1)% x (100 + additional bonus 2)%...\nThe Attack Speed of certain skills (such as attack-type mobility skills) will be corrected, and the actual speed will be lower than the result settled according to the above equation when the bonus received is quite high.\nAttack Speed is capped at 30 attacks per second.\n\nThe base Cast Speed is determined by the base cast interval of skills.\nThe final Cast Speed of a skill = 1/base Cast Interval of the skill x (100 + all non-additional bonuses)% x (100 + additional bonus 1)% x (100 + additional bonus 2)%...\nCast Speed is capped at 30 spells per second.\n\nThere is a certain chance to deal a Critical Strike when dealing hit damage.\nFinal Critical Strike Rating = Base Critical Strike Rating x (100 + all non-additional bonuses)% x (100 + additional bonus 1)% x (100 + additional bonus 2)%...\nCritical Hit Chance = Final Critical Strike Rating/100\nWhen attacking, the base Critical Strike Rating of the weapon will be factored in when calculating the Critical Strike Rating of the skill.\nWhen casting a spell, the base Critical Strike Rating of the spell will be factored in when calculating the Critical Strike Rating of the skill.\n\nThe type of damage dealt can be converted. For example, \"Converts 50% of Physical Damage to Fire Damage\".\nOnly Hit Damage can be converted.\nIf the sum of the conversion percentages of multiple damage types from the same source exceeds 100%, such as when \"Converts 60% of Physical Damage to Fire Damage\" and \"Converts 60% of Physical Damage to Cold Damage\" take effect at the same time, the final converted damage will not exceed 100%, and the damage will be redistributed according to their weighted percentages.\nConverted damage benefits from the bonuses of the original damage type and the bonuses of the post-conversion damage type. Non-additional bonuses can be stacked.\nFrostfire's damage bonus conversion is a special bonus, and only one bonus can be generated in each damage calculation.\n\nWhen dealing damage, if the attacker has Resistance Penetration of a certain type, the defender's Resistance will be reduced accordingly by the value of the Resistance Penetration when calculating the damage.\nResistance Penetration does not change the value of the defender's Resistance.\nResistance Penetration takes effect on all forms of damage (Hit, DoT, Secondary, Reflect).\n\nThere is a chance to deal Double Damage on hit according to the Double Damage chance.\nAll Double Damage chances that apply to the damage are stacked before the final determination.\n\nThe Affliction debuff is inflicted on enemies at the same time as Damage Over Time. All DoT effects share the same Affliction effect. When under the effect of Affliction, the enemy gradually accumulates Affliction according to the Affliction inflicted every second by the character up to the maximum amount of 100 Affliction.\nEach point of Affliction increases the Damage Over Time taken by the enemy by an additional 1% (up to 50% at 100 Affliction). This effect is affected by the Affliction debuff.\n\nWhen Reaping, the active Damage Over Time on the target will be settled at once according to the given time.\nReaping only applies to DoT you deal. The DoT dealt by other units can't be settled by your Reaping.\nReaping directly removes the target's HP, so it will not trigger any damage-dealing events.\nReaping generally has a cooldown time, which is affected by the Reaping Cooldown Recovery Speed instead of the general Cooldown Recovery Speed.\nThe DoT duration settled by Reaping is affected by affix bonuses such as: \"+X% Reaping Duration\".\n\nAilments include the following 6 types:\nIgnite: A debuff that deals Fire Damage Over Time.\nFrostbite: A debuff that slows enemies.\nFreeze: A debuff that makes enemies unable to move.\nShock: A debuff that makes subsequent hits deal Secondary Lightning Damage.\nTrauma: A debuff that deals Physical Damage Over Time.\nWilt: A debuff that deals Erosion Damage Over Time.\nAilments are generally inflicted by hits.\n\nIgnite, Shock, Trauma, and Wilt deal damage to enemies and are referred to as Ailment Damage.\nThe amount of Ailment Damage dealt is based on the base damage of the corresponding ailment, which is 0 by default.\nThe damage dealt by ailments has nothing to do with the damage dealt by a hit.\n\nOn hit, an ailment determination is carried out according to the chance of inflicting the corresponding ailment.\nIn the case of Frostbite, this effect will be inflicted if the Ailment determination is successful.\nIn the case of damage-dealing ailments, the ailment will be inflicted if the base damage of the corresponding ailment is not 0. If it is 0, the ailment will not be inflicted.\n\nIgnite deals Fire DoT with a default duration of 4s.\nAfter Igniting an enemy, Fire Damage equal to the Base Ignite Damage is dealt to the target every second.\nBy default, Ignite has the following effect: \"+30% additional Affliction effect\".\nThe default maximum number of Ignite Damage stacks is 1. This can be increased by upgrading the maximum number of stacks later. When a unit is under the effect of more than 1 Ignite effect, the first N (Ignite limit) stacks of Ignite that deal the most damage will take effect.\n\nFrostbite reduces the target's Attack Speed, Cast Speed, and Movement Speed by 10% with an initial duration of 1.5s.\nWhen the target is inflicted with Frostbite, an attack inflicts 2 points of Frostbite Rating for every 0.2% of the sum of the enemy's Max Life and Max Energy Shield reduced by the Cold Damage dealt by this hit.\nWhen a unit has more than 100 points of Frostbite Rating, the unit will be frozen for 0.2s and cannot take action while frozen.\nThe Frostbite effect and Freeze duration are increased by 1% for every 1 Frostbite Rating a unit has.\nIn general, legendary bosses are immune to Freeze but can be inflicted with a certain amount of Frostbite Rating up to an upper limit. Once this upper limit is reached, the Frostbite Rating will not continue to increase.\n\nWhen hitting an enemy with a Shock buff, Secondary Lightning Damage is dealt based on the Base Shock Damage of this buff.\nWhen hitting an enemy with a Shock buff, Hit Damage is guaranteed to trigger Shock Damage.\nEach Shock effect can only be triggered up to 12 times.\nThe base duration of the Shock buff is 4s.\nWhen hitting an enemy with a Shock buff, Secondary Lightning Damage is dealt based on the recorded Base Shock Damage, and this damage bonus is obtained when it is triggered.\nThe maximum valid buff stacks of the Shock buff is 1. This can't be changed by any affixes. When multiple Shock buffs exist concurrently, the stack with the highest Base Damage takes effect.\nThe character and their minions gain Base Shock Damage equal to 3% of the Lightning Damage hit at the beginning.\n\nTrauma deals Physical Damage Over Time with a default duration of 4s.\nWhen inflicting Trauma on an enemy, deals Physical Damage Over Time equal to the Base Trauma Damage to the target every second.\nBy default, Trauma has the following effect: \"+30% additional Reaping duration\".\nThe default maximum number of Trauma Damage stacks is 1 stack, and it can't be increased. When multiple Trauma effects exist concurrently on the same target, only the Trauma effect that deals the most damage will take effect.\n\nWilt deals Erosion Damage Over Time with a default duration of 1s.\nAfter inflicting Wilt on an enemy, Erosion DoT equal to the Base Wilt Damage is dealt to the target every second for each stack of Wilt.\nWilt has no default maximum number of stacks, but the number of its stacks may be limited by certain affixes. When the number of stacks is limited, Wilt Damage is dealt according to the stack that deals the most damage.\n\nSpell Burst: Automatically casts a Spell Skill a certain number of times.\nWhen Spell Burst is fully charged, casting Spell Skill will activate Spell Burst, which will consume all stacks of Spell Burst charged and automatically cast the Spell Skill the same number of times as the number of stacks consumed.\nSkills that are cast by Spell Burst, skills that have a cooldown, as well as Summon, Sentry, and Channeled Skills cannot trigger Spell Burst.\nThe Spell Skill that activates the Spell Burst is considered a skill cast by Spell Burst.\nSpell Burst Charge cannot go beyond Spell Burst's upper limit.\nSpell Burst can only be cast when Max Spell Burst is no lower than 1.\nSpell Burst will be fully charged within 2s. Spell Burst Charge Speed will increase the restoration speed of Spell Burst Charge.\n\nMultistrike: An Attack Skill that automatically performs a certain number of consecutive attacks.\nWhen using an Attack Skill, there is a chance to automatically perform an additional attack with the same Attack Skill after attacking. Additional attacks will not trigger further additional attacks. If the chance exceeds 100%, one additional attack will be performed with every 100% of the chance. If the chance is lower than 100%, this will be the corresponding chance of perfoming an additional attack after attacking.\nMultistrikes consume skill resources as normal and will be interrupted if there are insufficient resources. Moving or using other non-instant skills will interrupt Multistrike.\nMobility, Channeled, and Sentry Skills cannot Multistrike.\nDuring Multistrike, Attack Speed +20% by default.\nDuring Multistrike, for each additional attack. the damage of the Attack Skill will increase additionally based on the Multistrike damage increment attribute (the second attack receives the bonus once, the third attack receives the bonus twice, and so on).\nThe Multistrike damage increment attribute is affected by Multistrike damage increment bonuses, which multiplies the Multistrike damage increment by (1+additional percentage of increase).\n\nCommand is a base attribute that Hunters get after equipping a skill that can summon Synthetic Troops. The minimum value is -100, the maximum value is 100, and the initial value is 0. Command is generally not negative, but some special effects will reduce it to lower than 0.\nEvery point of Command will grant Synthetic Troop Minions +2% additional damage and increase the size of their Tracking Area. When Command is a negative value, the damage bonus will always be 0%, but the Tracking Area will be reduced accordingly.\nWhen Command is not 0, 13 points will be reduced/granted (depending on whether the current Command is positive or negative) per second until Command becomes 0 again. For every 10 Command increased (or decreased), the amount of Command reduced/granted per second +7 until the total Command becomes 0.\n\nGrowth is a base attribute every Spirit Magus possesses, with a minimum value of 100 and a maximum value of 1,000.\nSpirit Magus start off at Stage 1 (100 Growth) and grow into the next stage with every 100 Growth gained until they reach Stage 5 (500 Growth).\nWith every stage they grow, a Spirit Magus gains +5% Physique and +10% additional Skill Area. The also gain different skill and attribute enhancements:\nAt Stage 2, Spirit Magi have a +30% chance to use Enhanced Skills.\nAt Stage 3, the effect of Spirit Magi's Enhanced Skills are enhanced.\nAt Stage 4, Spirit Magi's Empower Skills gain new effects.\nAt Stage 5, all the attributes of Spirit Magi are increased, and they gain +25% additional damage, +10% additional Skill Area, and +30% additional Movement Speed. Their Tracking Area also increases.","season":"SS14","authorityScope":"ss14-site-deployment","rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"ffb303522910edc98e9de4a9957686dbf8ed0ece995c5ce649aa44fb723df83b"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Ring_of_Ice","sourcePageSha256":"15a6cfdb18cdef5e0e10fc4b2a799947a637f823a6015b770461933bd494527f"}},"ko/Armor":{"sourceUrl":"https://tlidb.com/ko/Armor","sourcePageSha256":"ded5d3479e4b2d4bddc708413c4e05dac7d51a934d984c2e5c8037e91c2ecdb0","locale":"ko","slug":"Armor","title":"Armor","body":"투구, 흉갑, 장갑, 신발 포함\n\n아머는 적중, 간접 대미지, 반사 대미지에 대한 방어 수단입니다.\n유저의 초기 아머는 0입니다. 아머는 최소 0입니다.\n아머가 제공하는 비물리 대미지에 대한 대미지 감소율은 60%%만 적용됩니다.\n아머는 최대 80%%의 대미지 감소를 제공합니다.\n유저가 대미지를 받기 전, 유저의 아머 대미지 감소율 공식:\n유저 대미지 감소율 = 유저 아머 수치 / ( 0.9 * 유저 아머 수치 + 3000 + 300 * Min(적 레벨, 90))\n몬스터가 대미지를 입히기 전, 몬스터 아머의 대미지 감소율 공식:\n몬스터 대미지 감소율 = 몬스터 아머 수치 / ( 0.9 * 몬스터 아머 수치 + 30000 )\n이 중 몬스터의 아머 수치는 레벨에 따라 증가하며, 최저 0, 최대 27273입니다.\n이중 아머\n대미지를 입을 때 아머 수치의 2배값으로 해당 회차의 대미지 감소를 판정합니다. 받는 대미지의 계산 과정에서 적용되며, 실제 아머 수치가 변경되는 것은 아닙니다.","season":"SS14","authorityScope":"ss14-site-deployment","rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"8d24a93fa884368ee6a67301f17f8ed1a6dc3cdc0ddd5925206856c7c0013a61"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Ring_of_Ice","sourcePageSha256":"dfd1e5d35d3f335e948a92220323f3c03394f87d20413e6dae000cdc91aeb941"}},"ko/Resistance":{"sourceUrl":"https://tlidb.com/ko/Resistance","sourcePageSha256":"5997bfc86b82d21fdb8c5c9e1b365a76c58118284a0a1e9013611f9ec536dbd5","locale":"ko","slug":"Resistance","title":"Resistance","body":"원소 저항 +15%\n원소 상태 이상 회피 확률 +20%\n\n유효 부식 저항 1%당 원소 상태 이상 회피 확률 +1%\n\n저항은 백분율 형식으로 해당 유형 대미지를 직접 감면하는 효과적인 생존 수단입니다.\n저항은 화염 저항, 번개 저항, 냉기 저항, 부식 저항 4가지로 나뉩니다. 이 중 화염 저항, 번개 저항, 냉기 저항을 원소 저항이라고 합니다.\n몬스터의 높은 대미지는 주로 원소 대미지이며, 해당 저항이 상승하면 높은 원소 대미지를 효과적으로 피할 수 있습니다.\n유효 저항.\n유저의 초기 원소 저항 및 부식 저항은 0입니다.\n모든 저항의 기본 상한은 60%%이며, %% 최대 저항에 의해 변경 가능합니다. 저항 상한은 최대 90%%입니다.\n최종적으로 유효한 저항은 유저의 현재 저항과 최대 저항의 최소값입니다.","season":"SS14","authorityScope":"ss14-site-deployment","rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"8d24a93fa884368ee6a67301f17f8ed1a6dc3cdc0ddd5925206856c7c0013a61"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Ring_of_Ice","sourcePageSha256":"dfd1e5d35d3f335e948a92220323f3c03394f87d20413e6dae000cdc91aeb941"}},"ko/Resistance_Penetration":{"sourceUrl":"https://tlidb.com/ko/Resistance_Penetration","sourcePageSha256":"22e54cd6499313808b9f35b26d8f3d7768681866512df4828326394f53617518","locale":"ko","slug":"Resistance_Penetration","title":"Resistance Penetration","body":"대미지 계산 시 더 낮은 수치로 방어자 저항을 계산합니다.\n저항에 대항하는 속성으로, 대미지 계산 과정에서 방어자에게 유효한 저항에 작용합니다.\n대미지를 입힐 때 공격자가 어떤 저항 관통을 보유하고 있을 경우, 대미지 계산 시 방어자의 해당 저항에서 상응되는 값을 뺍니다.\n저항 관통은 방어자의 실제 저항 수치를 바꾸지는 않습니다.\n저항 관통은 모든 대미지 형식(적중, 지속, 간접, 반사)에 유효합니다.","season":"SS14","authorityScope":"ss14-site-deployment","rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"8d24a93fa884368ee6a67301f17f8ed1a6dc3cdc0ddd5925206856c7c0013a61"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Ring_of_Ice","sourcePageSha256":"dfd1e5d35d3f335e948a92220323f3c03394f87d20413e6dae000cdc91aeb941"}},"ko/Armor_DMG_Mitigation_Penetration":{"sourceUrl":"https://tlidb.com/ko/Armor_DMG_Mitigation_Penetration","sourcePageSha256":"abb5bc16246f26378bcee5c4e1cadfb929652886a2391daa62fb3962452ddc4a","locale":"ko","slug":"Armor_DMG_Mitigation_Penetration","title":"Armor DMG Mitigation Penetration","body":"대미지 계산 시 방어자의 아머 대미지 감소 비율을 더 낮은 수치로 계산합니다.\n적중 대미지 계산 시, 공격자가 아머 대미지 감소 관통을 보유하고 있을 경우, 방어자의 아머 대미지 감소 비율에서 해당 수치를 차감합니다.\n아머 대미지 감소 관통은 실제 아머 수치에는 변화를 주지 않습니다.\n아머 대미지 감소 관통은 아머의 대미지 감소 비율을 마이너스로 감소시켜, 해당 수치로 방어자가 받는 대미지를 별도 추가시킵니다.","season":"SS14","authorityScope":"ss14-site-deployment","rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"8d24a93fa884368ee6a67301f17f8ed1a6dc3cdc0ddd5925206856c7c0013a61"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Ring_of_Ice","sourcePageSha256":"dfd1e5d35d3f335e948a92220323f3c03394f87d20413e6dae000cdc91aeb941"}},"ko/Lucky":{"sourceUrl":"https://tlidb.com/ko/Lucky","sourcePageSha256":"10ac952f8a3126480fc296db70dcc23bec1715e978b5a8c1aeec429ba9ebae1f","locale":"ko","slug":"Lucky","title":"Lucky","body":"두 번의 랜덤 판정 또는 수치 중 가장 유리한 결과 적용\n\n전투 중 일부 무작위 결과는 행운의 영향을 받습니다. 행운 시 해당 결과는 여러 번 판정되어 더 유리한 결과를 유지하고, 불행 시 더 불리한 결과를 유지하며, 둘은 서로 상쇄될 수 있습니다.\n행운과 불행\n전투 중 일부 무작위 결과(예: 대미지 수치, 크리티컬, 막기, 회피 등)는 행운과 불행의 영향을 받으며, 결과의 판정 횟수를 변경하여 적용됩니다.\n· 행운: 해당 결과를 두 번 판정하여, 더 유리한 결과를 유지합니다.\n· 슈퍼 행운: 해당 결과를 세 번 판정하여, 가장 유리한 결과를 유지합니다.\n· 불행: 해당 결과를 두 번 판정하여, 더 불리한 결과를 유지합니다.\n행운과 불행이 동시에 존재할 경우 서로 상쇄됩니다. 슈퍼 행운과 불행이 동시에 존재할 경우 상쇄되어 행운이 됩니다.","season":"SS14","authorityScope":"ss14-site-deployment","rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"8d24a93fa884368ee6a67301f17f8ed1a6dc3cdc0ddd5925206856c7c0013a61"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Ring_of_Ice","sourcePageSha256":"dfd1e5d35d3f335e948a92220323f3c03394f87d20413e6dae000cdc91aeb941"}},"ko/Spell_Burst":{"sourceUrl":"https://tlidb.com/ko/Spell_Burst","sourcePageSha256":"980a37de740bc4a163e87fbd3687d610dbb2337dadeb18d8b1b6452de9340e92","locale":"ko","slug":"Spell_Burst","title":"Spell Burst","body":"주술 스킬을 일정 횟수 자동으로 사용한다.\n매직 버스트가 최대 충전 상태가 되면, 다음 주술 스킬 사용 시 매직 버스트가 활성화된다. 매직 버스트로 충전 횟수가 전부 소모되며, 상응 횟수의 주술 스킬을 자동 사용한다.\n쿨타임이 있는 스킬, 촉발 스킬 또는 보초병, 채널링, 콤보 등 스킬은 매직 버스트를 활성화할 수 없다.\n\n영웅의 지략\n\n폭발이 폭발술로 변경되며, 매직 버스트 활성화를 허용한다.\n해당 특성 중 공격만으로만 발동되는 모든 조건이 적중 시 발동되는 것으로 변경된다.\n기본 특성에서 근접전 스킬 사용 시 분노를 생성하는 효과가 스킬 사용 시 분노를 생성하는 것으로 변경된다. 공격 적중 시 폭발을 발동하는 효과가 적중 시 폭발술을 발동하는 것으로 변경된다.\n\n히어로 특성 한정: 버서커·리한|분노의 불꽃\n\n관념 유도꾼\n\n시공간의 환상이 매직 버스트 소모 시, 유가에게도 매직 버스트 소모를 시도한다.\n매직 버스트 적중 대미지 별도 -20%\n\n히어로 특성 한정: 시공간의 증인·유가|시공간의 환상\n\n제5우주 속도\n\n매직 버스트 충전 속도 추가 -99%\n스킬 사용 시 100% 확률로 매직 버스트 충전을 2 회 즉시 획득한다. 간격 0.03초\n매직 버스트 적중 대미지 별도 -20%\n\n히어로 특성 한정: 시공간의 증인·유가|시공간의 환상\n\n착실한 접근\n\n시전 속도의 보너스와 추가 보너스의 100%가 매직 버스트 충전 속도에도 동일하게 적용된다.\n매직 버스트 충전 속도 추가 -33%\n매직 버스트가 시전한 스킬 적중 대미지 별도 +40%\n\n스퀴드 익스플로젼\n\n매직 버스트로 시전하는 스킬의 적중 대미지 별도 +16%, 10 초간 지속한다.\n\n주술 프로그램\n\n해당 스킬로 소환한 소환체의 최대 매직 버스트 +1, 주술 대미지 별도 +5%\n\n효과: 버스트\n\n매직 버스트로 시전하는 스킬의 적중 대미지 별도 +5%\n매직 버스트 충전이 최대치 도달 시 25 미터 내의 가장 가까운 적에게 메인 주술 스킬을 발동하고, 메인 주술 스킬의 매직 버스트 활성화를 시도한다.\n이동 속도-30%\n\n버스트 가압\n\n매직 버스트 최대치 +1\n\n버스트 초과부하\n\n매직 버스트 최대치 +2\n해당 스킬 쿨타임 +1 초, 매직 버스트를 활성화할 수 없다.\n\n주술 스킬을 일정 횟수 자동으로 시전합니다.\n매직 버스트\n매직 버스트가 최대 충전 상태가 되면 주술 스킬 사용 시 매직 버스트가 활성화됩니다. 매직 버스트 활성화 시 충전 중첩 횟수를 전부 소모하고 자동으로 주술 스킬을 시전합니다. 시전 횟수는 소모된 충전 중첩 횟수와 동일합니다.\n매직 버스트로 시전되는 스킬이나 쿨타임이 있는 스킬 또는 소환, 보초병, 채널링, 발동된 스킬은 매직 버스트를 활성화할 수 없습니다.\n매직 버스트가 활성화된 회차의 주술 스킬은 매직 버스트로 시전된 스킬로 간주합니다.\n매직 버스트 충전은 매직 버스트 상한을 초과할 수 없습니다. 매직 버스트 상한을 1 이상 보유한 경우에만 매직 버스트를 활성화할 수 있습니다.\n매직 버스트 충전 속도\n매직 버스트 충전은 2초 안에 완료됩니다. 매직 버스트 충전 속도는 매직 버스트 충전의 회복 속도를 증가시킵니다.\n매직 버스트 충전 회복 시간 = 2 / ((100+매직 버스트 충전 속도)% * (100+추가 매직 버스트 충전 속도1)% * (100+추가 매직 버스트 충전 속도2)%...)\n\nSpell Burst\n\nTorchlight Infinite season 3 new spell mechanic: Spell Burst.\n\nAdded an upgrade system for spell skills. Consume spell burst when using or triggering channeled spell skills. According to the number of spell burst stacks consumed, automatically cast multiple spell skills in a burst in a short period of time.\n\n- When Spell Burst is fully charged, casting a Spell Skill will activate Spell Burst. When Spell Burst is cast, it will consume all stacks charged and cast the Spell Skill a number of times equal to the number of stacks consumed.\n\n- Skills that have a cooldown, Summon, Sentry, and Channeled Skills cannot activate Spell Burst.\n\n- The Spell Skill that activates the Spell Burst is considered a skill cast by Spell Burst.\n\n- Spell Burst Charge cannot go beyond Spell Burst's upper limit.\n\n- At least 1 Max Spell Burst is required before Spell Burst can be cast.\n\n- Spell Burst Charge will be fully charged in 2s.\n\n- Spell Burst Charge Speed will increase the restoration speed of Spell Burst Charge.\n\nSpell Burst Guides\n\nWe have designed spell burst, a new developed system for spells with spell burst. Hunters can consume spellburst Stacks when using or triggering Channel spell skills based on the number of spellburst stacks consumed. They can automatically cast multiple spell skills in a burst within a short period of time allowing for easy semi-automatic spell casting.\n\nSpell Burst is a powerful development system for spells. It enables Hunters to have a relaxed and smooth map clearing experience. It also allows them to move around neatly avoid enemy damage. However spellpers can only be consumed when it's at maximum Stacks. So, don't forget to upgrade the charge speed of Spell Burst when upgrading cast speed. We believe the additional of spell burst will bring spells to prominence.","season":"SS14","authorityScope":"ss14-site-deployment","rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"8d24a93fa884368ee6a67301f17f8ed1a6dc3cdc0ddd5925206856c7c0013a61"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Ring_of_Ice","sourcePageSha256":"dfd1e5d35d3f335e948a92220323f3c03394f87d20413e6dae000cdc91aeb941"}},"ko/Double_Damage":{"sourceUrl":"https://tlidb.com/ko/Double_Damage","sourcePageSha256":"be73366e301eefaaa04f41c867f4c734d946473ee370daa926d621143b7f8ec0","locale":"ko","slug":"Double_Damage","title":"Double Damage","body":"적군 적중 시, 일정 확률로 해당 공격으로 인한 대미지가 2배로 증가한다.\n\n적중 시, 일정 확률로 해당 회차의 대미지가 2배가 됩니다.\n적중 시, 이중 대미지 부여 확률에 따라 확률적으로 해당 회차의 대미지가 2배가 됩니다.\n판정 시, 해당 회차 대미지에 유효한 모든 이중 대미지의 확률을 중첩 후 판정합니다.\n이중 대미지 확률은 적중 대미지에만 유효합니다.","season":"SS14","authorityScope":"ss14-site-deployment","rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"8d24a93fa884368ee6a67301f17f8ed1a6dc3cdc0ddd5925206856c7c0013a61"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Ring_of_Ice","sourcePageSha256":"dfd1e5d35d3f335e948a92220323f3c03394f87d20413e6dae000cdc91aeb941"}},"ko/Critical_Strike":{"sourceUrl":"https://tlidb.com/ko/Critical_Strike","sourcePageSha256":"4d0c167fd5f0f5168a22f9a1c1953d95e41f5db01f928d7c972926bd3e1dcf22","locale":"ko","slug":"Critical_Strike","title":"Critical Strike","body":"적중 대미지를 입힐 때, 일정 확률로 크리티컬이 발동됩니다.\n적중 대미지를 입힐 때 일정 확률로 크리티컬이 발동됩니다. 스킬 한 번으로 여러번 적중 시(예: 나선 공격), 종종 크리티컬 1회로 판정됩니다.\n크리티컬\n공격 시, 무기의 기본 크리티컬이 해당 스킬의 크리티컬 계산에 관여합니다. 시전 시, 주술의 기본 크리티컬이 해당 스킬의 크리티컬 계산에 관여합니다.\n최종 크리티컬=기본 크리티컬의 합*(1+모든 비추가 비율 보너스)*(1+추가 비율 보너스1)*(1+추가 비율 보너스2)...\n크리티컬의 확률=최종 크리티컬/100\n크리티컬 대미지\n모든 유닛은 기본 150%의 크리티컬 대미지를 보유합니다.\n크리티컬 시, 해당 회차의 적중으로 주는 대미지가 원래의 대미지*크리티컬 대미지 비율로 증가합니다.","season":"SS14","authorityScope":"ss14-site-deployment","rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"8d24a93fa884368ee6a67301f17f8ed1a6dc3cdc0ddd5925206856c7c0013a61"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Ring_of_Ice","sourcePageSha256":"dfd1e5d35d3f335e948a92220323f3c03394f87d20413e6dae000cdc91aeb941"}},"ko/Character_Build":{"sourceUrl":"https://tlidb.com/ko/Character_Build","sourcePageSha256":"ec1a3c21804af3384e19fffe4cfa32af976ab36c4776776fb42a5c9040264a85","locale":"ko","slug":"Character_Build","title":"Character Build","body":"HP가 0이되면 유닛이 처치됩니다.\n\n최대 HP\n히어로의 초기 최대 HP는 50입니다.\n1레벨 상승할 때마다 최대 HP가 13씩 증가합니다.\n힘 1포인트 당 최대 HP가 0.2포인트씩 증가합니다.\n\n관련 속성\n힘\n최대 HP\n최대 HP %\n최대 HP 추가%\n\nHP 지속 회복\n관련 속성\n초당 HP 자연 회복\n초당 HP % 자연 회복\nHP 자연 회복 속도\n\nHP 반환\n적중 시 캐릭터가 손실한 HP 중 일부를 즉시 반환합니다. HP 반환 한도는 30%입니다.\n반환 시 반환 간격이 존재하며, 기본 간격은 0.5초입니다.\n관련 속성\n% HP 반환\n반환 간격 추가%\n\n순간 회복\n옵션에 해당하는 사건 발생 시, 즉시 HP를 일정량 회복합니다.\n예:\n중상을 입을 경우, 손실된 HP의 35% 회복\n처치 시 HP 5% 회복\n\n보호막은 방어 속성의 하나로, 대미지 저항 시 HP보다 먼저 카운트됩니다.\n\n최대 보호막\n히어로는 초기 보호막이 없습니다. 보호막 기본값은 재능, 장비, 스킬 등을 바탕으로 제공됩니다.\n지혜 1포인트 당 최대 보호막이 0.05% 증가합니다.\n관련 속성\n최대 보호막\n최대 보호막 %\n최대 보호막 추가%\n해당 장비의 보호막\n해당 장비의 보호막 %\n\n일정 시간동안 대미지를 입지 않고(HP 소모, 대미지 완화 제외), 현재의 보호막의 수치가 최대 보호막보다 낮을 경우, 보호막이 충전되기 시작합니다. 기본 충전 간격은 2초입니다. 캐릭터의 최대 보호막이 0일 경우, 보호막은 충전되지 않습니다. 히어로의 초기 보호막 충전량은 초당 20%입니다.\n관련 속성\n%보호막 충전 속도\n보호막 충전 속도 추가%\n%충전 간격\n보호막 충전 간격 추가%\n\n적중 시 캐릭터가 손실된 보호막의 일부를 즉시 반환합니다. 보호막 반환 한도는 30%입니다.\n반환 시 반환 간격이 존재하며, 기본 간격은 0.5초입니다.\n관련 속성\n%보호막 반환\n반환 간격 추가%\n\n옵션에 해당하는 사건 발생 시, 즉시 보호막을 일정량 회복합니다.\n예:\n회피 시 손실한 보호막의 12% 회복\n막기 시 보호막 5% 회복\n\nMP는 스킬 시전에 사용됩니다. 현재의 MP가 스킬 시전에 필요한 양보다 적을 경우 스킬을 시전할 수 없습니다.\n\n최대 MP\n히어로의 초기 최대 MP는 40입니다.\n1레벨 상승할 때마다 최대 MP가 5씩 증가합니다.\n지혜 1포인트 당 최대 MP가 0.5 증가합니다.\n최대 보호막 계산 규칙\n관련 속성\n지혜\n최대 MP\n%최대 MP\n최대 MP 추가%\n\n히어로의 초기 MP 자연 회복량은 초당 7포인트입니다.\n히어로의 초기 MP 자연 회복량은 1.75%입니다.\n관련 속성\n초당 MP 자연 회복\n초당 MP 자연 회복%\n%MP 자연회복 속도\n\n옵션에 해당하는 사건 발생 시, 즉시 MP를 일정량 회복합니다.\n예:\n적중 시, MP 5 회복\n스킬 사용 시, MP 1% 회복\n\n몬스터 대미지 유형에는 물리, 화염, 서리, 번개, 부식, 총 다섯 가지가 있습니다.\n그중 화염, 서리, 번개 대미지를 원소 대미지라고 합니다.\n높은 대미지의 몬스터 스킬은 주로 원소 스킬이며, 상응하는 원소 저항 향상 시 효과적으로대량의 원소 대미지 면역이 가능합니다.\n\n히어로의 초기 원소 저항 및 부식 저항은 0입니다. 48레벨, 58레벨, 80레벨 달성 시 히어로의 모든 저항이 20% 감소됩니다.\n모든 저항의 기본 상한은 75%이며, 최대 저항 %에 의해 변경될 수 있습니다. 저항 상한은 최대 95%입니다.\n최종적으로 유효한 저항은 유저의 현재 저항과 최대 저항의 최소값입니다.\n관련 속성\n%저항\n%최대 저항\n\n저항에 대항하는 속성으로, 대미지 계산 과정에서 방어자에게 유효한 저항에 작용합니다.\n대미지를 입힐 때 공격자가 어떤 저항 관통을 보유하고 있을 경우, 대미지 계산 시 방어자의 해당 저항에서 상응하는 값을 뺍니다.\n저항 관통은 방어자의 저항 속성 값을 바꾸지 않습니다.\n저항 관통은 모든 대미지 형식(적중, 지속, 간접, 반사)에 유효합니다.\n\n저항 무시 보유 시, 대미지 계산 과정에서 저항과 저항 관통을 무시합니다.\n\n아머는 적중, 간접 및 반사 대미지에 대한 방어 수단입니다.\n캐릭터의 초기 아머와 최소 아머는 0입니다.\n관련 속성\n아머\n아머%\n아머 추가 %\n해당 장비의 아머\n해당 장비의 아머%\n\n아머를 통한 대미지 감소율=아머/(0.9*아머+30000), 아머를 통한 대미지 감소 상한은 80%입니다.\n비물리 대미지의 경우, 아머를 통한 대미지 감소는 60%만 적용됩니다.\n\n이중 아머\n대미지를 입을 때 아머의 2배 값으로 해당 회차의 대미지 감소를 판정합니다. 받는 대미지의 계산 과정에서만 유효하며, 실제 아머는 변하지 않습니다.\n\n회피는 적중 대미지에 대한 방어 수단 중 하나로, 적중 대미지를 1회 회피할 때마다, 해당 적중은 명중 및 후속 효과를 유발하지 않으며, 대미지도 입힐 수도 없습니다. 회피 확률은 공격자의 명중률과 피공격자의 회피율에 따라 결정됩니다.\n\n히어로가 몬스터에게 부여하는 적중은 회피할 수 없습니다.\n회피 수치\n캐릭터의 초기 회피 수치와 최소 회피 수치는 0입니다.\n1레벨 상승할 때마다 회피 수치가 3포인트 증가합니다.\n민첩 1포인트당 회피 수치가 0.02% 증가합니다.\n관련 속성\n회피 수치\n회피 수치%\n추가% 회피 수치\n해당 장비의 회피 수치\n해당 장비의 회피 수치%\n\n회피율\n회피율=1~1.15*공격자의 명중 수치/(공격자 명중 수치+0.5*방어자의 회피 수치^0.75), 공격자의 명중 수치와 방어자의 회피 수치에 따라 결정됩니다.\n최대 회피율은 75%이며, 최저값은 0%입니다.\n기본 상황에서 주술 대미지 회피 시, 회피 수치가 40% 별도 감소합니다.\n현재 몬스터의 최대 명중 수치는 1247입니다.\n\n막기는 적중과 반사 대미지에 대한 방어 수단입니다. 적중 혹은 반사 대미지를 입을 때, 공격자의 공격, 주술 태그 및 해당 히어로의 공격, 주술 막기 확률에 따라 막기 성공 여부가 판정됩니다. 막기 성공 시 막기 비율과 추가 막기 대미지에 따라 대미지가 감면됩니다.\n\n히어로의 초기 막기 확률은 0입니다. 막기 확률에는 공격 막기 확률과 주술 막기 확률이 포함되며, 태그된 대미지를 받을 경우 막기 성공 여부가 독립적으로 판정됩니다. 출처가 다른 막기 확률은 중첩되며, 최대 100%까지 중첩됩니다.\n관련 속성\n%막기 확률\n%공격 막기 확률\n%주술 막기 확률\n히어로의 초기 막기 비율은 35%, 상한은 75%입니다. 막기 성공 판정 후, 막기 비율에 따라 해당 대미지가 차감됩니다.\n초기에는 히어로에게 추가 막기 대미지가 없습니다. 막기 비율과 막기 고정값을 동시 보유한 경우, 막기 비율을 먼저 계산한 뒤 막기 고정값이 계산됩니다.\n관련 속성\n%막기 비율\n추가 막기 대미지\n\n대미지 면역은 적중 대미지, 반사 대미지 및 간접 대미지에 대한 방어 수단입니다. 출처가 다른 대미지 면역 확률은 중첩됩니다.\n초기 히어로가 보유한 대미지 면역 확률은 0%입니다.\n대미지 면역 성공 시 적중 된 것으로 간주되며, 공격자의 적중 관련 효과는 발동 되지만, 대미지와 후속 상태 이상 및 제어 효과를 받지 않습니다.\n관련 속성\n%대미지 면역 확률\n\n받는 대미지의 별도 감소는 모든 유형의 대미지에 대한 방어 수단입니다. 받는 대미지의 출처가 다를 경우 별도 감소량이 독립적으로 계산됩니다.\n\n받는 대미지별 별도 감소를 통해 획득하는 대미지 감면의 최대 한도는 90%입니다.\n\n대미지 완화는 적중 대미지에 대한 방어 수단입니다. 적중 대미지를 입을 때, 받은 대미지의 일부가 직접카운트 되지 않고, 직후의 4초 동안 특수한 형식으로 0.5초에 1번씩 대미지를 합니다. 대미지 완화로 카운트된 대미지는 다른 태그의 영향을 받지 않으며, 대미지와 관련된 사건이 발동되지도 않습니다. 출처가 다른 대미지 완화 비율은 중첩됩니다.\n\n방어자가 입는 대미지의 감면량을 계산하는 과정에서, 대미지 전환을 통해 받는 대미지의 유형을 변경시키고, 전환 후 해당 대미지 유형에 대해 감면량을 계산합니다. 출처가 다른 대미지 전환 비율은 중첩됩니다. 100%를 초과할 경우 각 출처의 비율에 따라 다시 분배됩니다.\n\n기본 지속 시간은 10초입니다. [강건한 축복] 중첩 1회당 받는 대미지가 4% 별도로 감소합니다. [강건한 축복]은 기본적으로 최대 4회 중첩 가능합니다.\n[강건한 축복]의 기본 지속 시간은 10초입니다.\n[강건한 축복]획득 시, 모든 [강건한 축복]의 지속 시간이 새로고침됩니다. [강건한 축복]의 지속 시간이 종료되면, 모든 [강건한 축복]을 상실합니다.\n\n[황홀한 축복] 중첩 1회당 6%의 이동 속도, 공격 속도 및 시전 속도를 제공합니다. [황홀한 축복]은 기본적으로 최대 4회 중첩 가능합니다.\n[황홀한 축복]의 기본 지속 시간은 10초입니다.\n[황홀한 축복] 획득 시, 모든 [황홀한 축복]의 지속 시간이 새로고침됩니다. [황홀한 축복]의 지속시간이 종료되면, 모든[황홀한 축복]을 상실합니다.\n\n[집요한 축복] 중첩 1회당 이중 대미지 확률 4%를 제공합니다. [집요한 축복]은 기본적으로 최대 4회 중첩 가능합니다.\n[집요한 축복]의 기본 지속 시간은 10초입니다.\n[집요한 축복] 획득 시 모든 [집요한 축복]의 지속 시간이 새로고침됩니다. [집요한 축복]의 지속시간이 종료되면, 모든 [집요한 축복]을 상실합니다.\n\n전의 상태에서 몬스터 처치, 강적 적중 시 전의를 1포인트 획득합니다.\n전의의 기본 효과: 전의 1포인트 당 공격 및 주술 크리티컬 수치 2% 증가, 전의는 최대 100포인트 획득 가능.\n기본 지속시간은 10초입니다.\n\n최대 HP와 보호막의 20%만큼 대미지를 흡수할 수 있는 보호막을 획득합니다.\n장벽의 기본 흡수 비율은 50%입니다.\n장벽이 지속되는 동안은 장벽을 획득할 수 없습니다.\n장벽의 지속 시간이 종료되거나, 장벽의 수치가 0이되면 장벽을 상실합니다.\n기본 지속 시간은 10초입니다.\n\n방황 획득 시, 방황을 100포인트 획득한다.\n1초마다 최대 방황의 10%가 감소하며, 0이 되면 방황을 상실한다.\n방황 기본 효과: 방황 1포인트당, 회피 수치 및 대미지 면역 확률이 0.3%씩 증가한다.\n최대 방황 100\n\n최대 5회 중첩 가능합니다.\n기본 지속 시간은 5초입니다.\n몰두 획득 시, 몰두 상태의 지속 시간이 새로고침됩니다.\n몰두 상태는 스킬, 장비 등에 따라 서로 다른 버프를 제공합니다.\n\n받는 대미지 25% 별도 감소, 최대 1회 중첩 가능.\n기본 지속 시간은 4초입니다.\n경화 상태는 보조 스킬 [경화 제공]을 통해서만 획득할 수 있습니다.\n\n받는 대미지 별도 추가 10%, 최대 1회 중첩 가능.\n기본 지속 시간은 4초입니다.\n마비는 제어형 상태에에 속합니다.\n\n중첩 1회당 공격 속도, 시전 속도, 이동 속도가 6% 감소하며, 최대 5회 중첩 가능합니다.\n기본 지속 시간은 4초입니다.\n감속 상태 부여 시, 감속 상태의 지속 시간이 새로고침됩니다.\n감속은 제어형 상태에 속합니다.\n\n현재 게임 내 주요 대미지 형식은 다음 4가지가 있습니다.\n적중 대미지\n지속 대미지\n간접 대미지\n반사 대미지\n\n적중 대미지는 보통 공격이나 주술을 통해 부여되며, 한 번에 카운트 되는 대미지입니다. 특별한 설명이 없을 경우, 스킬로 주는 대미지는 모두 적중 대미지입니다.\n\n다음은 적중 대미지의 고유 메커니즘입니다:\n명중/회피\n크리티컬\n대미지 유형 전환/추가\n이중 대미지\n대미지 전이\n대미지 완화\n막기\n면역\n중상\n\n지속 대미지는 일정 시간 동안 끊임없이 타겟에게 대미지를 줍니다.\n스킬로 주는 지속 대미지는 스킬 효과로서 '스킬 효과 지속 시간 10% 증가'등의 옵션의 영향을 받을 수 있습니다.\n\n다음은 지속 대미지의 고유 메커니즘입니다:\n심화\n수확\n\n간접 대미지는 보통 어떤 행위의 부가효과로 나타납니다. 예)\"처치 시 적이 폭발한다\"\n간접 대미지는 적중 대미지도 아니고, 지속 대미지도 아니기 때문에, 적중 및 지속 대미지의 특수 메커니즘에 의해 강화될 수 없습니다.\n\n모든 대미지가 반드시 다음 5가지 유형 중 한가지에 속합니다:\n물리\n화염\n냉기\n번개\n부식\n\n적중 물리 대미지는 아머에 의해 감면될 수 있으며, 그 외 대미지의 모든 형식(적중, 지속, 간접, 반사)은 해당되는 저항에 의해 감면될 수 있습니다.\n\n대부분의 속성들 처럼, 공격자가 주는 대미지의 최종 수치=기본 대미지*(100+모든 비추가 보너스)%*(100+추가 보너스1)%*(100+추가 보너스2)%...\n\n공격 속도의 기본값은 무기의 공격 속도에 의해 결정됩니다.\n무기의 공격 속도는 무기의 기본 속도와 해당 무기의 공격 속도에 영향을 주는 무기 옵션에 의해 결정됩니다.\n듀얼 상태일 경우 무기 공격 속도는 두 무기의 평균값입니다.\n대부분의 상황에서 캐릭터의 최종 공격 속도=무기 공격 속도*(100+모든 비 추가 보너스)%*(100+추가 보너스1)%*(100+추가 보너스2)%...\n일부 스킬(예:공격류 위치 이동 스킬)의 실제 공격 속도는 수정되며, 보너스가 비교적 높을 경우 실제 속도는 상술한 카운트 결과보다 낮습니다.\n공격 속도 상한은 초당 30회 입니다.\n\n시전 속도의 기본값은 스킬의 기본 시전 간격에 따라 결정됩니다.\n어떤 스킬의 최종 시전 속도=1/해당 스킬의 기본 시전 간격*(100+모든 비추가 보너스)%*(100+추가 보너스1)%*(100+추가 보너스2)%...\n시전 속도 상한은 초당 30회입니다.\n\n적중 대미지를 입힐 때, 일정 확률로 크리티컬이 발동됩니다.\n최종 크리티컬 =기본 크리티컬*(100+모든 비추가 보너스)%*(100+추가 보너스1)%*(100+추가 보너스2)%...\n크리티컬 확률=최종 크리티컬/100\n공격 시 무기의 기본 크리티컬이 스킬의 크리티컬 계산에 참여합니다.\n시전 시 주술의 기본 크리티컬이 스킬의 크리티컬 계산에 참여합니다.\n\n대미지 유형간의 전환이 가능합니다. 예: \"물리 대미지의 50%가 화염 대미지로 전환된다\".\n대미지 전환은 적중 대미지에만 유효합니다.\n여러개의 동일한 출처의 대미지 유형 전환 비율의 총합이 100%를 초과할 경우, 예를 들어 \"물리 대미지의 60%가 화염 대미지로 전환/물리 대미지의 60%가 냉기 대미지로 전환\" 두가지가 동시에 유효할 경우, 최종 전환되는 대미지는 100%를 초과할 수 없으며, 비율의 가중치가 다시 분배됩니다.\n전환된 대미지에는 원래의 대미지 유형과 목표 대미지 유형에 대한 보너스가 모두 적용되며, 추가 보너스 이외에는 모두 중첩 계산됩니다.\n빙염술사의 대미지 보너스가 특수 보너스로 전환되어, 대미지를 1회 계산할 때마다 보너스는 1회만 생성됩니다.\n\n대미지를 줄 때 공격자가 어떤 저항 관통을 보유하고 있을 경우, 대미지를 계산할 때 방어자의 해당 저항에서 상응하는 값을 뺍니다.\n저항 관통은 방어자의 저항 속성 값을 바꾸지 않습니다.\n저항 관통은 모든 대미지 형식(적중, 지속, 간접, 반사)에 유효합니다.\n\n적중 시, 이중 대미지 부여 확률에 따라 확률적으로 해당 회차의 대미지가 2배가 됩니다.\n판정 시, 해당 회차 대미지에 유효한 모든 이중 대미지의 확률을 중첩 후 판정합니다.\n\n적에게 지속 대미지를 입힐 때 심화 디버프가 동시에 부여된다. 모든 지속 대미지가 심화 효과 하나를 공유한다. 심화 보유 시, 캐릭터의 '초당 시전 심화' 속성에 따라 적에게 심화 수치가 점차 누적되며, 누적 상한은 100이다.\n심화 1포인트 당 적이 받는 지속 대미지가 1% 별도 추가된다(100포인트=100%), 이 효과는 심화 효과의 영향을 받는다.\n\n수확을 부여할 경우, 타깃에게 있는 모든 유효한 지속 대미지에 대해, 설정된 시간에 따라 총 대미지를 1회 카운트합니다.\n수확은 자신이 입힌 지속 대미지에만 적용되며, 다른 유닛이 입힌 지속 대미지는 자신의 수확으로 카운트되지 않습니다.\n수확은 타깃의 HP를 직접적으로 제거하기 때문에, 대미지를 주는 다른 사건은 발동되지 않습니다.\n수확은 일반적으로 쿨타임을 가집니다. 해당 쿨타임은 수확 쿨타임 회복 속도의 영향을 받으며, 일반 쿨타임 회복 속도의 영향을 받지 않습니다.\n수확 시간은 '수확 시간 X% 증가'와 같은 옵션으로 보너스를 획득할 수 있습니다.\n\n상태이상에는 다음 6가지가 있습니다.\n점화: 지속적으로 화염 대미지를 주는 디버프 효과\n빙결: 적을 감속시키는 디버프 효과\n동결: 적을 행동할 수 없게 만드는 디버프 효과\n감전: 후속 적중으로 추가 간접 번개 대미지를 주는 디버프 효과\n외상: 지속적으로 물리 대미지를 주는 디버프 효과\n몰락: 지속적으로 부식 대미지를 주는 디버프 효과\n상태 이상은 보통 적중 시 부여됩니다.\n\n점화, 감전, 외상, 몰락으로 적에게 대미지를 줄 수 있으며, 이를 상태이상 대미지라고 합니다.\n상태이상 대미지의 크기는 해당 상태이상 기본 대미지에 의해 결정되며, 기본적으로는 0입니다.\n상태이상 대미지와 적중 시 주는 대미지는 무관합니다.\n\n적중 시, 해당되는 상태이상의 확률에 따라 상태 이상을 판정합니다.\n빙결에 대한 상태이상 판정 성공시, 빙결이 부여됩니다.\n대미지형 상태이상에 대한 상태이상 판정 성공 시, 해당되는 상태이상 기본 대미지가 0이 아닐 경우 해당 상태 이상을 부여하며, 0일 경우 부여되지 않습니다.\n\n점화는 지속적으로 화염 대미지를 주며, 초기 지속 시간은 4초입니다.\n적에게 점화를 입힐 경우, 1초마다 기본 점화 대미지에 해당하는 지속 화염 대미지를 입힙니다.\n점화는 기본적으로 '심화 효과 30% 별도 추가' 효과를 가지고 있습니다.\n점화 대미지는 기본적으로 최대 1회 중첩 가능하며, 성장을 통해 중첩 한도를 높일 수 있습니다. 여러개의 점화가 하나의 유닛에 동시에 존재할 경우, 대미지가 높은 N(점화 중첩 상한)번째 점화가 적용됩니다.\n\n빙결은 타겟의 공격, 시전 및 이동 속도를 10% 감소시키며, 초기 지속 시간은 1.5초입니다.\n타겟에게 빙결을 입힐 때, 해당 적중 대미지로 주는 냉기 대미지가 적의 최대 HP와 최대 보호막을 합친 값의 0.2%에 도달하면 빙결 2포인트를 시전합니다.\n유닛 하나의 누적 빙결이 100포인트를 초과할 경우, 해당 유닛은 0.2초간 동결됩니다. 동결된 유닛은 움직일 수 없습니다.\n유닛이 가진 빙결 1포인트당 유닛이 받는 빙결 효과와 동결 시간이 1% 증가합니다.\n일반적으로 레전드 보스는 동결에 면역되지만, 빙결 상한을 가지고 있습니다. 최대치에 도달하면 더이상 빙결이 증가되지 않습니다.\n\n감전 버프를 가진 적 적중 시, 해당 버프의 기본 감전 대미지로 간접 번개 대미지가 카운트됩니다.\n몬스터가 감전 버프 보유 시, 해당 몬스터에 대한 적중 대미지는 무조건 감전이 카운트됩니다.\n감전 1회당 최대 12번까지만 카운트이 유지됩니다.\n감전 버프의 기본 지속 시간은 4초입니다.\n감전 버프를 가진 적 적중 시, 기록된 기본 감전 대미지에 따라 간접 번개 대미지를 카운트합니다. 해당 회차의 대미지 보너스는 카운트 시 획득합니다.\n감전 버프는 최대 1회까지 유효하며, 어떤 옵션에도 변경되지 않습니다. 동시에 여러개의 감전 버프가 존재할 경우, 감전 기본 대미지가 가장 높은 버프가 적용됩니다.\n캐릭터 및 소환체가 최초 획득하는 기본 감전 대미지는 적중 번개 대미지의 3%입니다.\n\n외상은 지속적으로 물리 대미지를 입히며, 초기 지속 시간은 4초입니다.\n적에게 외상 부여 시 1초마다 기본 외상 대미지 만큼의 지속 물리 대미지를 입힙니다.\n외상은 기본적으로 \"수확 시간 30% 별도 추가\"효과를 가집니다.\n외상 대미지는 기본적으로 최대 1회 중첩 가능하며, 중첩 횟수는 증가할 수 없습니다. 유닛 하나에 여러 개의 외상이 동시에 존재할 경우, 대미지가 가장 높은 외상이 적용됩니다.\n\n몰락은 지속적으로 부식 대미지를 주며, 초기 지속 시간은 1초입니다.\n적에게 몰락 부여 시, 몰락 중첩 1회당 1초마다 기본 몰락 대미지 만큼의 지속 부식 대미지를 입힙니다.\n몰락은 기본적으로 무제한 중첩 가능하지만, 일부 옵션들에 의해 중첩 횟수가 제한을 받을 수 있습니다. 중첩 횟수 제한이 있을 경우, 대미지가 가장 높은 몰락 대미지가 적용됩니다.\n\n매직 버스트: 주술 스킬을 일정 횟수 자동으로 시전합니다.\n매직 버스트가 최대 충전상태가 되면 주술 스킬 시전 시 매직 버스트가 활성화됩니다. 매직 버스트 활성화 시 충전 중첩 횟수를 전부 소모하며, 자동으로 주술 스킬을 시전합니다. 주술 스킬의 시전 횟수는 소모된 충전 중첩 횟수와 동일합니다.\n매직 버스트로 시전되는 스킬이나 쿨타임이 있는 스킬 또는 소환, 보초병, 채널링 스킬은 매직 버스트를 활성화할 수 없습니다.\n매직 버스트가 활성화된 회차의 주술 스킬은 매직 버스트로 시전된 스킬로 간주합니다.\n매직 버스트 충전은 매직 버스트 최대치를 초과할 수 없습니다.\n매직 버스트 최대치를 1 이상 보유한 경우에만 매직 버스트를 시전할 수 있습니다.\n매직 버스트 충전 시 2초 안에 매직 버스트 충전 속도가 회복 완료되어, 매직 버스트의 회복 속도를 증가시킵니다.\n\n연속 공격: 공격 스킬을 일정 횟수만큼 자동으로 연속하여 시전합니다.\n공격 스킬 사용 시, 일정 확률로 공격 후 해당 공격 스킬을 자동으로 1회 재사용합니다. 연속 공격 중에는 연속 공격 효과가 재발동되지 않습니다. 연속 공격 확률이 100%를 초과하는 경우, 공격 종료 후 반드시 1회 자동 공격하며, 초과된 부분의 경우 확률 100%당 자동 공격을 1회 추가 진행합니다. 100% 미달 부분의 경우, 자동 공격이 끝난 후 해당 확률에 따라 자동 공격을 1회를 재진행합니다.\n연속 공격 시에는 스킬 자원을 정상적으로 소모하며, 자원 부족 시 연속 공격이 중단됩니다. 이동 또는 기타 비순간 스킬을 사용하는 경우에도 연속 공격이 중단됩니다.\n이동, 채널링, 보초병 시전 스킬은 연속 공격이 불가능합니다.\n연속 공격 시 공격 속도가 기본 20% 증가합니다.\n연속 공격 시, 공격이 1회 추가될 때마다 해당 스킬의 대미지가 연속 공격의 체증 속성에 따라 별도로 추가합니다(두 번째 공격 시 보너스 1회, 세 번째 공격 시 보너스 2회, 같은 방식으로 계속).\n연속 공격 체증 속성은 육성되며, 연속 공격 체증 수치는 곱하기합니다(1+추가 체증 백분율).\n\n통솔은 유저가 스마트 웨폰 소환 스킬을 장착한 후 보유하는 자원의 일종으로, 초기 0, 최저 -100, 최고 100입니다. 통솔은 일반적으로 음수가 아니나, 일부 특수효과의 영향으로 0 미만이 될 수 있습니다.\n통솔 1포인트 당, 스마트 웨폰 소환체의 대미지가 2% 별도 추가하고, 정찰 범위가 증가합니다. 통솔이 음수일 경우, 대미지 보너스는 0%으로 고정되나 정찰 범위는 상응하게 감소합니다.\n통솔이 0이 아닌 경우, 0이 될 때까지 초당 13포인트씩 회복(증가/감소, 현재 통솔에 따라 결정)되며, 통솔 10(또는 -10)포인트 당 초당 회복값이 7포인트씩 증가합니다.\n\n성장치는 마령이 선천적으로 보유하는 자원의 일종으로, 최저 100, 최고 1000입니다.\n마령은 최초 1티어(성장치 100포인트 보유)로 시작하며, 성장치 100포인트 당 1티어씩 성장하며 최고 5티어(성장치 500)까지 성장할 수 있습니다.\n마령은 승급 시마다 체격이 5% 증가하고, 스킬 범위가 10% 별도 추가하며, 스킬 및 속성 또한 다음과 같이 강화됩니다:\n2티어로 성장 시, 마령의 강화 스킬 사용 확률 30% 증가\n3티어로 성장 시, 마령의 강화 스킬 효과 강화\n4티어로 성장 시, 마령의 자극 스킬에 신규 효과 발생\n5티어로 성장 시, 마령의 속성 전면 향상, 대미지 25% 별도 추가, 스킬 범위 10% 별도 추가, 이동 속도 30% 별도 추가. 마령 정찰 범위 증가.","season":"SS14","authorityScope":"ss14-site-deployment","rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"8d24a93fa884368ee6a67301f17f8ed1a6dc3cdc0ddd5925206856c7c0013a61"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Ring_of_Ice","sourcePageSha256":"dfd1e5d35d3f335e948a92220323f3c03394f87d20413e6dae000cdc91aeb941"}}}};
